import speech_recognition as sr
import time

# Initialize the recognizer
recognizer = sr.Recognizer()

# List of audio files to transcribe
audio_files = ['audio1.wav', 'audio2.wav']

def transcribe_audio(file):
    # Load the audio file
    with sr.AudioFile(file) as source:
        audio = recognizer.record(source)

    try:
        # Transcribe the audio using Google Speech Recognition
        transcript = recognizer.recognize_google(audio)
        return transcript
    except sr.UnknownValueError:
        print(f"Could not understand audio {file}")
    except sr.RequestError as e:
        print(f"Could not request results from Google Speech Recognition service; {e}")

def poll_transcription_job(file):
    max_retries = 10
    retry_count = 0

    while retry_count < max_retries:
        try:
            transcript = transcribe_audio(file)
            if transcript:
                return transcript
            else:
                print(f"Retrying transcription for {file} (Attempt {retry_count + 1})")
                time.sleep(2)  # Wait for 2 seconds before retrying
                retry_count += 1
        except sr.RequestError:
            print(f"Could not connect to Google Speech Recognition service. Retrying in 5 seconds...")
            time.sleep(5)

    return None

# Batch transcribe the audio files
for file in audio_files:
    transcript = poll_transcription_job(file)
    if transcript:
        print(f"Transcript for {file}:")
        print(transcript)
    else:
        print(f"Failed to transcribe {file} after multiple attempts.")
